python3 << 'PYEOF'
import os, json

api_key_file = os.environ.get('GALAXY_API_KEY_FILE', '')
with open(api_key_file) as f:
    api_key = f.read().strip()

from bioblend.galaxy import GalaxyInstance
gi = GalaxyInstance(url='https://usegalaxy.org', key=api_key)

history_id = 'bbd44e69cb8906b5de3c2eaab0dd8932'
tool_id = 'toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'

# Try using the 21.01 format with nested JSON
inputs = {
    "operation": {
        "selector": "evolutionary_rate",
        "input_mode": {
            "selector": "grouped_zip_archives",
            "archives": [
                {
                    "label": "animals",
                    "archive": {"src": "hda", "id": "f9cad7b01a4721353a48ab203c219c97"},
                    "filter_suffix": "treefile"
                },
                {
                    "label": "fungi",
                    "archive": {"src": "hda", "id": "f9cad7b01a47213596469f7b0ed0612b"},
                    "filter_suffix": "treefile"
                }
            ]
        }
    }
}

try:
    result = gi.tools.run_tool(history_id, tool_id, inputs, input_format='21.01')
    print(f"Job submitted successfully!")
    print(f"Job ID: {result}")
    print(json.dumps(result, indent=2))
except Exception as e:
    print(f"Error: {e}")
    # Try alternative approach
    print("\nTrying alternative...")
    try:
        # Some versions of BioBlend use create_tool_job instead
        if hasattr(gi.tools, 'create_tool_job'):
            result = gi.tools.create_tool_job(tool_id, inputs, history_id)
            print(f"Job created: {result}")
        else:
            print("No create_tool_job method")
    except Exception as e2:
        print(f"Alternative error: {e2}")
PYEOF

